import { afterEach, describe, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import Storage from '@deepseek-ai/dsh-storage'
import SessionProjectionRegistry from '@deepseek-ai/dsh-session-projection'
import { DomainFacility } from '@deepseek-ai/dsh-storage-domain'
import { SessionId } from '@deepseek-ai/dsh-session'
import { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import { provideQuietTokenMeter } from './helpers/team-host-fixture.ts'
import { MemoryMediaPool, MemoryStorageBackend } from './helpers/memory-backend.ts'
import AgentTeam from '../src/index.ts'
import { agentTeamHumanActor } from '../src/ledger.ts'
import * as agentTeamInvariant from '../src/invariant.ts'
import type { Agent } from '@deepseek-ai/dsh-agent'
import type { UserMessage } from '@deepseek-ai/dsh-llm'
import type { AgentTeamProjectRef, AgentTeamMemberActor, AgentTeamRequestId, AgentTeamTaskRef } from '../src/types.ts'

const cleanups: Array<() => Promise<void>> = []
const alpha = WorkspaceId('workspace:alpha')
const requestId = (value: string): AgentTeamRequestId => value as AgentTeamRequestId

afterEach(async () => {
  await Promise.all(cleanups.splice(0).map(cleanup => cleanup()))
})

async function harness(): Promise<{ readonly ctx: Context }> {
  const ctx = new Context()
  await ctx.plugin(Storage)
  ctx.storage.backend.register('memory', new MemoryStorageBackend(new MemoryMediaPool()))
  const facility = new DomainFacility(ctx, { backend: 'memory', routes: {} })
  ctx.storage.mount('domain', facility)
  ctx.provide('storageDomain', facility)
  ctx.provide('workspaceRegistry', {
    get: (id: WorkspaceId) => id === alpha ? { id, path: process.cwd(), attachSession: async () => {}, archiveSession: async () => {} } : undefined,
    list: () => [{ id: alpha, path: process.cwd() }],
    archiveSession: async () => {},
  })
  ctx.provide('agents', { create: async () => { throw new Error('unused') }, resume: async () => { throw new Error('unused') } })
  ctx.provide('agentDefaultModel', { currentSelection: () => ({ provider: 'mock', model: 'mock' }) })
  ctx.provide('agentPresets', { mount: async () => { throw new Error('unused') } })
  ctx.provide('tools', { schemas: () => [] })
  ctx.provide('sessionPersistence', { list: async () => [] })
  provideQuietTokenMeter(ctx)
  await ctx.plugin(agentTeamInvariant)
  await ctx.plugin(SessionProjectionRegistry)
  const fiber = await ctx.plugin(AgentTeam)
  cleanups.push(async () => { await fiber.dispose(); await facility.closeAll() })
  return { ctx }
}

async function addLiveMember(ctx: Context, projectRef: AgentTeamProjectRef, handle: string): Promise<AgentTeamMemberActor> {
  const memberId = `member:agent-${crypto.randomUUID()}` as AgentTeamMemberActor['memberId']
  await ctx.agentTeam['ledger']!.addMember({
    requestId: requestId(`ledger-member-${handle}-${memberId}`), workspaceId: alpha, handle, description: 'Reads work', presetId: 'team-member',
    projectRefs: [projectRef], actor: agentTeamHumanActor(),
    member: {
      memberId, sessionId: SessionId(`session:${handle}-${memberId}`), workspaceId: alpha, handle, description: 'Reads work',
      presetId: 'team-member', privateMemoryPath: `/tmp/${handle}`, state: 'enabled' as const,
    },
  })
  return { kind: 'member', memberId, handle }
}

function wakeSeam(session: string): { readonly agent: Agent; readonly state: { readonly calls: UserMessage[] } } {
  const state = { calls: [] as UserMessage[] }
  const wake = (message: UserMessage): void => { state.calls.push(message) }
  const agent = {
    id: SessionId(`session:${session}`),
    status: 'idle',
    inbox: { nextTurn: [], nextStep: [], remove: () => {} },
    steer: wake,
    followup: wake,
  } as unknown as Agent
  return { agent, state }
}

/** Replies `times` as `member` and returns the Thread's newest revision. */
async function replyAs(ctx: Context, threadRef: string, revisionStart: number, times: number, member: AgentTeamMemberActor, tag: string): Promise<number> {
  let revision = revisionStart
  for (let index = 1; index <= times; index += 1) {
    const result = await ctx.agentTeam.replyForAgent(wakeSeam(`${tag}-${index}`).agent, { requestId: requestId(`${tag}-${index}`),
      workspaceId: alpha, threadRef: threadRef as never, body: `${tag} ${index}`, baseRevision: revision })
    if (result.kind !== 'committed') throw new Error(`expected a committed reply, got ${result.kind}`)
    revision = result.thread.revision
  }
  return revision
}

function report(label: string, state: { readonly calls: readonly UserMessage[] }): void {
  console.log(`\n########## ${label}: ${state.calls.length} notice(s) ##########`)
  for (const call of state.calls) console.log((call.content[0] as { text: string }).text)
}

describe('does a Task Thread creator keep receiving the Thread?', () => {
  it('A: owner creates a Task accountable to itself, another member replies five times', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('a-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const owner = await addLiveMember(ctx, projectRef, 'owner-a')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('a-own'), workspaceId: alpha, projectRef, memberId: owner.memberId })
    const other = await addLiveMember(ctx, projectRef, 'other-a')
    const ledger = ctx.agentTeam['ledger']!

    const started = await ledger.startThread({ requestId: requestId('a-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Build the gateway' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')

    const ownerSeam = wakeSeam('owner-a')
    const otherSeam = wakeSeam('other-a')
    ctx.agentTeam['handles'].set(owner.memberId, { agent: ownerSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(other.memberId, { agent: otherSeam.agent, dispose: async () => {} })

    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 5, other, 'a-reply')
    report('A owner (accountable=self) after 5 replies from another member', ownerSeam.state)
    report('A other member (non-owner follower) after 5 replies', otherSeam.state)
  })

  it('B: owner creates a Task accountable to another owner, a third member replies five times', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('b-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const creator = await addLiveMember(ctx, projectRef, 'creator-b')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('b-own1'), workspaceId: alpha, projectRef, memberId: creator.memberId })
    const accountable = await addLiveMember(ctx, projectRef, 'accountable-b')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('b-own2'), workspaceId: alpha, projectRef, memberId: accountable.memberId })
    const worker = await addLiveMember(ctx, projectRef, 'worker-b')
    const ledger = ctx.agentTeam['ledger']!

    const started = await ledger.startThread({ requestId: requestId('b-start'), actor: creator, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Ship the pipeline', accountable: accountable.memberId })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')

    const creatorSeam = wakeSeam('creator-b')
    const accountableSeam = wakeSeam('accountable-b')
    const workerSeam = wakeSeam('worker-b')
    ctx.agentTeam['handles'].set(creator.memberId, { agent: creatorSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(accountable.memberId, { agent: accountableSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(worker.memberId, { agent: workerSeam.agent, dispose: async () => {} })

    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 5, worker, 'b-reply')
    report('B creator owner after 5 replies from a third member', creatorSeam.state)
    report('B accountable owner after 5 replies', accountableSeam.state)
    report('B worker (non-owner follower) after 5 replies', workerSeam.state)
  })

  it('C: owner creates a Task accountable to itself, then a member mentions it directly', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('c-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const owner = await addLiveMember(ctx, projectRef, 'owner-c')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('c-own'), workspaceId: alpha, projectRef, memberId: owner.memberId })
    const other = await addLiveMember(ctx, projectRef, 'other-c')
    const ledger = ctx.agentTeam['ledger']!

    const started = await ledger.startThread({ requestId: requestId('c-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Audit the schema' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')

    const ownerSeam = wakeSeam('owner-c')
    const otherSeam = wakeSeam('other-c')
    ctx.agentTeam['handles'].set(owner.memberId, { agent: ownerSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(other.memberId, { agent: otherSeam.agent, dispose: async () => {} })

    await replyAs(ctx, started.value.thread.threadRef, started.value.thread.revision, 1, other, 'c-reply')
    report('C owner after ONE ordinary reply', ownerSeam.state)

    const mention = await ctx.agentTeam.replyForAgent(otherSeam.agent, { requestId: requestId('c-mention'), workspaceId: alpha,
      threadRef: started.value.thread.threadRef, body: `@owner-c please take a look`, baseRevision: ownerSeam.state.calls.length + 1, recipients: [owner.memberId] })
    if (mention.kind !== 'committed') throw new Error('expected a committed mention')
    report('C owner after a direct mention (with one ordinary reply outstanding)', ownerSeam.state)
  })

  it('D: owner creates a Task, the Task is closed, then a member replies five times', async () => {
    const { ctx } = await harness()
    const project = await ctx.agentTeam.createProject({ requestId: requestId('d-p'), workspaceId: alpha, name: 'engineering', description: 'Engineering' })
    const projectRef = project.project.projectRef
    const owner = await addLiveMember(ctx, projectRef, 'owner-d')
    await ctx.agentTeam.addProjectOwner({ requestId: requestId('d-own'), workspaceId: alpha, projectRef, memberId: owner.memberId })
    const worker = await addLiveMember(ctx, projectRef, 'worker-d')
    const ledger = ctx.agentTeam['ledger']!

    const started = await ledger.startThread({ requestId: requestId('d-start'), actor: owner, workspaceId: alpha, projectRef,
      kind: 'task', body: 'Tighten the tests' })
    if (started.value.kind !== 'committed') throw new Error('expected a committed start')
    const taskRef: AgentTeamTaskRef = started.value.task!.taskRef

    const ownerSeam = wakeSeam('owner-d')
    const workerSeam = wakeSeam('worker-d')
    ctx.agentTeam['handles'].set(owner.memberId, { agent: ownerSeam.agent, dispose: async () => {} })
    ctx.agentTeam['handles'].set(worker.memberId, { agent: workerSeam.agent, dispose: async () => {} })

    // The worker claims and finishes the Task; the owner closes it.
    const claim = await ctx.agentTeam.changeClaimForAgent(workerSeam.agent, { requestId: requestId('d-claim'), workspaceId: alpha,
      taskRef, action: 'claim', baseRevision: started.value.thread.revision, direction: 'Tighten the tests' })
    if (claim.kind !== 'committed') throw new Error('expected a committed claim')
    const done = await ctx.agentTeam.changeClaimForAgent(workerSeam.agent, { requestId: requestId('d-done'), workspaceId: alpha,
      taskRef, action: 'done', baseRevision: claim.thread.revision })
    if (done.kind !== 'committed') throw new Error('expected a committed done')
    const closed = await ctx.agentTeam.changeTask({ requestId: requestId('d-close'), workspaceId: alpha, taskRef,
      action: 'close', baseRevision: done.thread.revision })
    if (closed.kind !== 'committed') throw new Error('expected a committed close')
    ownerSeam.state.calls.length = 0

    await replyAs(ctx, started.value.thread.threadRef, closed.thread.revision, 5, worker, 'd-reply')
    report('D owner after the Task was closed and 5 replies arrived', ownerSeam.state)
  })
})

