}

export interface InboxThreadPlan {
  readonly threadRef: AgentTeamThreadRef
  readonly role: InboxScopeRole
  readonly delivery: InboxDelivery
}

export interface InboxDeliveryPlan {
  /** Why a notice goes out now, or `undefined` when nothing may interrupt the reader. */
  readonly trigger: InboxDelivery | undefined
  readonly signature: string
  readonly threads: readonly InboxThreadPlan[]
}

/**
 * Decide whether the reader's current unread interrupts it. Every fact a Thread
 * can hold is immediate: an ordinary update reaches the reader only because it
 * follows the Thread, a mention or reply carries a direct marker, and a
 * responsibility Activity or live Task reminder arrives through its own marker.
 * Attention decides whether ordinary work exists at all, never how fast it
 * travels, so no identity chooses a slower class here. `covered` is what keeps
 * an unchanged rederivation from spending a second attempt on the same facts.
 */
export function planInboxDelivery(input: InboxDeliveryPlan & { readonly threads: readonly InboxThreadUnread[] }): InboxDeliveryPlan {
  return planFrom(input.threads, input.main, input.covered)
}

function planFrom(
  threads: readonly InboxThreadUnread[],
  main: readonly InboxMainUnread[],
  covered: string | undefined,
): InboxDeliveryPlan {
  const immediate: (string | number)[][] = []
  const plans: InboxThreadPlan[] = []
  for (const { item, facts, reminders = [] } of input_thread(threads)) {
    const threadRef = item.thread.threadRef
    if (reminders.length > 0) immediate.push([threadRef, 'reminder', ...reminders.map(reminder => `${reminder.kind}:${reminder.baselineSequence}`)])
    const now = facts.map(entry => entry.fact.sequence)
    if (now.length > 0) immediate.push([threadRef, ...now])
    plans.push(Object.freeze({ threadRef, role: item.attention === undefined ? 'member' : 'follower', delivery: 'immediate' as const }))
  }
  for (const { projectRef, entries } of main) {
    if (entries.length > 0) immediate.push([projectRef, ...entries.map(entry => entry.sequence)])
  }
  const signature = immediate.length === 0 ? '' : JSON.stringify(immediate)
  const trigger = signature !== '' && signature !== covered ? 'immediate' : undefined
  return Object.freeze({ trigger, signature, threads: Object.freeze(plans) })
}

