    await team.ledger.postMainMessage({ requestId: team.rid('p2'), actor: human, workspaceId: alpha, projectRef: team.projectRef, body: '@m1 please look' })
    await team.ledger.changeAttention({ requestId: team.rid('f'), actor: team.actor, workspaceId: alpha, projectRef, action: 'follow' })
    await team.ledger.readMainStream({ requestId: team.rid('r'), actor: team.actor, workspaceId: alpha, projectRef: team.projectRef })
    let out = 'ok'
    try { const s = new AgentTeamLedger(team.table as never, { rulesVersion: 2 }); await s.initialize(); s.validateAtMount() } catch (e) { out = `THREW ${(e as Error).message}` }
    console.log('reopen =', out)
    expect(out).toBe('ok')
  })
})

describe('fix 2: non-member cannot follow or see the Main stream', () => {
  it('refuses the follow and shows no inbox row', async () => {
    const team = await seed(true)
    await expect(team.ledger.changeAttention({ requestId: team.rid('f'), actor: team.actor, workspaceId: alpha, projectRef: team.projectRef, action: 'follow' })).rejects.toThrow(/not_project_member/)
    await team.ledger.postMainMessage({ requestId: team.rid('p'), actor: human, workspaceId: alpha, projectRef: team.projectRef, body: 'secret project talk' })
    console.log('outsider inbox main =', JSON.stringify(team.ledger.memberInbox(team.actor, {}).main))
    console.log('outsider notificationFacts =', JSON.stringify(team.ledger.mainNotificationFacts(team.memberId as never).length))
    expect(team.ledger.memberInbox(team.actor, {}).main).toEqual([])
    expect(team.ledger.mainNotificationFacts(team.memberId as never)).toEqual([])
  })
})

describe('fix 3: a non-owner follower is woken, and so is the Human', () => {
  it('wakes both directions', async () => {
    const team = await seed()
    await team.ledger.changeAttention({ requestId: team.rid('f'), actor: team.actor, workspaceId: alpha, projectRef: team.projectRef, action: 'follow' })
    await team.ledger.postMainMessage({ requestId: team.rid('p1'), actor: human, workspaceId: alpha, projectRef: team.projectRef, body: 'from human' })
    let affected = team.ledger.affectedMembersOf((await recordsOf(team.table)).find(r => r.kind === 'team/main-message-posted') as never) as readonly string[]
    console.log('human post -> affected =', JSON.stringify(affected))
    expect(affected).toContain(team.memberId as string)
    expect(affected).toContain('member:human')
    await team.ledger.postMainMessage({ requestId: team.rid('p2'), actor: team.actor, workspaceId: alpha, projectRef: team.projectRef, body: 'from follower' })
    affected = team.ledger.affectedMembersOf((await recordsOf(team.table)).filter(r => r.kind === 'team/main-message-posted').at(-1) as never) as readonly string[]
    console.log('follower post -> affected =', JSON.stringify(affected))
    expect(affected).toContain('member:human')
    expect(affected).not.toContain(team.memberId as string)
    await team.ledger.startThread({ requestId: team.rid('t'), actor: human, workspaceId: alpha, projectRef: team.projectRef, kind: 'discussion', body: 'a discussion' })
    affected = team.ledger.affectedMembersOf((await recordsOf(team.table)).find(r => r.kind === 'team/thread-started') as never) as readonly string[]
    console.log('discussion -> affected =', JSON.stringify(affected))
    expect(affected).toContain(team.memberId as string)
  })
})

describe('fix 4: an owner grant keeps an existing follow', () => {
  it('keeps the watermark', async () => {
    const team = await seed()
    await team.ledger.changeAttention({ requestId: team.rid('f'), actor: team.actor, workspaceId: alpha, projectRef: team.projectRef, action: 'follow' })
    await team.ledger.postMainMessage({ requestId: team.rid('p1'), actor: human, workspaceId: alpha, projectRef: team.projectRef, body: 'one' })
    await team.ledger.postMainMessage({ requestId: team.rid('p2'), actor: human, workspaceId: alpha, projectRef: team.projectRef, body: 'two' })
    const before = team.ledger.mainStreamHistory(team.actor, { workspaceId: alpha, projectRef: team.projectRef }).standing.unreadCount
    await team.ledger.addProjectOwner({ requestId: team.rid('own'), actor: human, workspaceId: alpha, projectRef: team.projectRef, memberId: team.memberId as never })
    const after = team.ledger.mainStreamHistory(team.actor, { workspaceId: alpha, projectRef: team.projectRef }).standing.unreadCount
    console.log('unread before grant =', before, 'after grant =', after)
    expect(before).toBe(2)
    expect(after).toBe(2)
    let out = 'ok'
    try { const s = new AgentTeamLedger(team.table as never, { rulesVersion: 2 }); await s.initialize(); s.validateAtMount() } catch (e) { out = `THREW ${(e as Error).message}` }
    console.log('reopen =', out)
    expect(out).toBe('ok')
  })
})
